using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct RegionId : IEquatable<RegionId>, IComparable<RegionId>
    {
        public Guid Value { get; }

        public RegionId(Guid value)
        {
            Value = value;
        }

        public static RegionId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static RegionId NewRandom() => new RegionId(Guid.NewGuid());

        public static RegionId Parse(string text) => new RegionId(Guid.Parse(text));

        public static bool TryParse(string text, out RegionId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new RegionId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(RegionId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is RegionId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(RegionId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(RegionId left, RegionId right) => left.Equals(right);

        public static bool operator !=(RegionId left, RegionId right) => !left.Equals(right);
    }
}
